// Embedded SPIR-V (generated by vgrid_embed_shaders onto a PRIVATE include
// path).
#include "triangle_counts_comp.spv.hpp"
#include "triangle_offsets_comp.spv.hpp"

namespace volumetric_kit::grid::voxelize::detail {
namespace {

// The kernels' local size (triangle_counts.comp, triangle_offsets.comp).
constexpr std::uint32_t kLanes = 256;

// Mirror the push blocks of triangle_counts.comp and triangle_offsets.comp
// under scalar layout.
struct CountPush {
  volume::VoxelGridParams grid;
  std::uint32_t tri_count;
  std::uint32_t item_base = 0;
};
static_assert(sizeof(CountPush) == 40, "CountPush layout drift");
struct OffsetsPush {
  std::uint32_t size;
  std::uint32_t tri_count;
  std::uint32_t item_base = 0;
};
static_assert(sizeof(OffsetsPush) == 12, "OffsetsPush layout drift");

}  // namespace

MeshBand::~MeshBand() = default;

core::Result<std::unique_ptr<MeshBand>> MeshBand::create(
    core::Device& device, core::Allocator& allocator) {
  VKC_TRY(check_device_requirements(device, "MeshBand::create"));
  std::unique_ptr<MeshBand> band(new MeshBand());
  band->device_ = &device;
  band->allocator_ = &allocator;
  const VkPushConstantRange count_range{VK_SHADER_STAGE_COMPUTE_BIT, 0,
                                        sizeof(CountPush)};
  const VkPushConstantRange offsets_range{VK_SHADER_STAGE_COMPUTE_BIT, 0,
                                          sizeof(OffsetsPush)};
  core::KernelSetBuilder kb(device);
  VKC_TRY(kb.add(band->count_, "voxelize_triangle_counts",
                 vgrid_triangle_counts_comp_spv,
                 vgrid_triangle_counts_comp_spv_size, 5, &count_range));
  VKC_TRY(kb.add(band->finish_, "voxelize_triangle_offsets",
                 vgrid_triangle_offsets_comp_spv,
                 vgrid_triangle_offsets_comp_spv_size, 5, &offsets_range));
  VKC_ASSIGN(band->pool_, kb.build());
  VKC_ASSIGN(band->scan_,
             MeshScan::create(device, allocator, "voxelize.mesh_offsets_scan"));

  VkPhysicalDeviceProperties props{};
  vkGetPhysicalDeviceProperties(device.physical_device(), &props);
  band->max_workgroup_count_x_ = props.limits.maxComputeWorkGroupCount[0];
  band->max_storage_buffer_range_ = props.limits.maxStorageBufferRange;

  VKC_ASSIGN(band->flags_,
             core::device_storage_buffer(allocator, sizeof(std::uint32_t)));
  VKC_ASSIGN(band->result_buffer_,
             core::device_storage_buffer(allocator, sizeof(CountResult)));
  VKC_ASSIGN(band->bounds_, core::device_storage_buffer(
                                allocator, 6 * sizeof(std::int32_t)));
  band->count_.set.write_storage_buffer(3, band->flags_.handle(), 0,
                                        VK_WHOLE_SIZE);
  band->count_.set.write_storage_buffer(4, band->bounds_.handle(), 0,
                                        VK_WHOLE_SIZE);
  band->finish_.set.write_storage_buffer(3, band->flags_.handle(), 0,
                                         VK_WHOLE_SIZE);
  band->finish_.set.write_storage_buffer(4, band->result_buffer_.handle(), 0,
                                         VK_WHOLE_SIZE);
  return band;
}

core::Status MeshBand::grow(core::Buffer& buffer, VkDeviceSize bytes,
                            const char* name) {
  return core::ensure_device_scratch(*device_, *allocator_, buffer, bytes,
                                     max_storage_buffer_range_, name);
}

MeshBand::BlockRange MeshBand::bounds() const noexcept {
  if (result_.total == 0) return BlockRange{};
  const auto& b = bounds_host_;
  return BlockRange{Vec3i(b[0], b[1], b[2]), Vec3i(b[3], b[4], b[5]), false};
}

core::Status MeshBand::set_mesh(const volume::VoxelGridParams& grid,
                                const Vec3f* vertices,
                                std::uint32_t vertex_count,
                                const std::uint32_t* indices,
                                std::uint32_t triangle_count, const char* who) {
  const std::string name = who;
  host_vertices_ = nullptr;
  host_indices_ = nullptr;
  vertex_count_ = 0;
  triangle_count_ = 0;
  result_ = {};
  if (triangle_count == 0) return {};
  if (vertices == nullptr || indices == nullptr) {
    return core::Status::invalid_argument(name +
                                          ": vertices or indices is null");
  }
  // Every array is per-call and bound whole, so each is checked against what
  // one binding may cover -- first, since each size is known from the counts
  // alone.
  const VkDeviceSize vertex_bytes = VkDeviceSize(vertex_count) * sizeof(Vec3f);
  const VkDeviceSize index_bytes =
      VkDeviceSize(triangle_count) * 3 * sizeof(std::uint32_t);
  const VkDeviceSize offset_bytes =
      (VkDeviceSize(triangle_count) + 1) * sizeof(std::uint32_t);
  const struct {
    const char* what;
    VkDeviceSize bytes;
  } ranges[] = {
      {"the vertex buffer", vertex_bytes},
      {"the index buffer", index_bytes},
      {"the candidate offsets", offset_bytes},
  };
  for (const auto& r : ranges) {
    VKC_TRY(core::check_storage_buffer_range((name + ": " + r.what).c_str(),
                                             r.bytes,
                                             max_storage_buffer_range_));
  }
  // The one index check: the kernels index the vertex buffer directly, and
  // robustBufferAccess is enabled nowhere in this repo.
  const std::size_t index_count = 3 * std::size_t{triangle_count};
  for (std::size_t i = 0; i < index_count; ++i) {
    if (indices[i] >= vertex_count) {
      return core::Status::invalid_argument(
          name + ": a triangle index is at or past vertex_count");
    }
  }
  VKC_TRY(grow(vertices_, vertex_bytes, "voxelize.mesh_vertices"));
  VKC_TRY(grow(indices_, index_bytes, "voxelize.mesh_indices"));
  VKC_TRY(grow(offsets_, offset_bytes, "voxelize.mesh_offsets"));
  VKC_TRY(scan_->prepare(offsets_, triangle_count + 1));
  grid_ = grid;
  host_vertices_ = vertices;
  host_indices_ = indices;
  vertex_count_ = vertex_count;
  triangle_count_ = triangle_count;
  return {};
}

core::Status MeshBand::record_count(core::CommandBatch& batch,
                                    core::GpuStageScope* stage) {
  result_ = {};
  if (triangle_count_ == 0) return {};
  const std::uint32_t size = triangle_count_ + 1;  // the total's slot last
  VKC_TRY(batch.upload(vertices_, 0, host_vertices_,
                       VkDeviceSize(vertex_count_) * sizeof(Vec3f), stage));
  VKC_TRY(batch.upload(indices_, 0, host_indices_,
                       VkDeviceSize(triangle_count_) * 3 *
                           sizeof(std::uint32_t),
                       stage));
  VKC_TRY(batch.fill(flags_, 0, flags_.size(), 0u));
  // The range starts empty: INT_MAX minima, INT_MIN maxima.
  VKC_TRY(batch.fill(bounds_, 0, 3 * sizeof(std::int32_t), 0x7FFFFFFFu));
  VKC_TRY(batch.fill(bounds_, 3 * sizeof(std::int32_t),
                     3 * sizeof(std::int32_t), 0x80000000u));

  const auto bind = [](const core::ComputeKernel& kernel,
                       std::uint32_t binding, const core::Buffer& buffer) {
    kernel.set.write_storage_buffer(binding, buffer.handle(), 0, VK_WHOLE_SIZE);
  };
  bind(count_, 0, vertices_);
  bind(count_, 1, indices_);
  bind(count_, 2, offsets_);
  bind(finish_, 0, offsets_);
  bind(finish_, 1, scan_->first());
  bind(finish_, 2, scan_->root());

  const CountPush count_push{grid_, triangle_count_};
  VKC_TRY(volumetric_kit::grid::detail::dispatch_items(
      batch, count_, count_push, size, kLanes, max_workgroup_count_x_,
      stage));
  VKC_TRY(scan_->record(batch, size, stage));
  const OffsetsPush offsets_push{size, triangle_count_};
  VKC_TRY(volumetric_kit::grid::detail::dispatch_items(
      batch, finish_, offsets_push, size, kLanes, max_workgroup_count_x_,
      stage));
  VKC_TRY(batch.readback(result_buffer_, 0, sizeof(result_), &result_));
  VKC_TRY(batch.readback(bounds_, 0, sizeof(bounds_host_),
                         bounds_host_.data()));
  return {};
}

core::Status MeshBand::settle_count(const char* who) const {
  if (result_.refused != 0) {
    return core::Status::invalid_argument(
        std::string(who) +
        ": candidate blocks exceed 2^32 -- is the mesh scaled to the grid's "
        "units (metres)?");
  }
  return {};
}

}  // namespace volumetric_kit::grid::voxelize::detail
